using Azure.AI.OpenAI;
using OpenAI.Chat;
using System.ClientModel;

public class DirectOpenAiTicketClassifier
{
    private readonly ChatClient _chatClient;

    public DirectOpenAiTicketClassifier(string endpoint, string apiKey, string deploymentName)
    {
        var azureClient = new AzureOpenAIClient(
            new Uri(endpoint),
            new ApiKeyCredential(apiKey));

        _chatClient = azureClient.GetChatClient(deploymentName);
    }

    public async Task<(string Category, int Urgency)> ClassifyTicketAsync(string ticketText, CancellationToken ct = default)
    {
        var messages = new ChatMessage[]
        {
            new SystemChatMessage("You are a ticket triage classifier. Return only 'Category|Urgency' where Urgency is 1-5."),
            new UserChatMessage($"Ticket: {ticketText}")
        };

        var options = new ChatCompletionOptions
        {
            Temperature = 0.1f,
            MaxOutputTokenCount = 50
        };

        ClientResult<ChatCompletion> result = await _chatClient.CompleteChatAsync(messages, options, ct);
        var text = result.Value.Content[0].Text.Trim();

        var parts = text.Split('|');
        return (parts[0].Trim(), int.Parse(parts[1].Trim()));
    }
}

using Microsoft.Extensions.AI;

public class AbstractedTicketClassifier
{
    private readonly IChatClient _chatClient;

    public AbstractedTicketClassifier(IChatClient chatClient)
    {
        _chatClient = chatClient;
    }

    public async Task<(string Category, int Urgency)> ClassifyTicketAsync(string ticketText, CancellationToken ct = default)
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a ticket triage classifier. Return only 'Category|Urgency' where Urgency is 1-5."),
            new(ChatRole.User, $"Ticket: {ticketText}")
        };

        var options = new ChatOptions
        {
            Temperature = 0.1f,
            MaxOutputTokens = 50
        };

        ChatCompletion response = await _chatClient.CompleteAsync(messages, options, ct);
        var text = response.Message.Text?.Trim() ?? string.Empty;

        var parts = text.Split('|');
        return (parts[0].Trim(), int.Parse(parts[1].Trim()));
    }
}

